cookie_file = cache_dir / "instsci-cookies.json"

_probe_state = {"last": 0.0}

def _detect(context: Any, page: Any) -> bool:
    """WebVPN 登录判定：必须由网关实测通过，不能只看 cookie 是否存在。

    为什么不能用「有没有 wengine_vpn_ticket」当判据：该 cookie 在登录之前
    网关就会下发，名字与形态和正式会话票据无法区分，据此返回成功会保存
    一批无效 cookie，让后续所有机构请求都以为「会话有效」。
    这里改为：用浏览器当前的 cookie 真去请求一个经 WebVPN 转换过的 URL，
    只有不再被踢回 CAS/登录页才算真正登录完成。
    """
    import time as _time

    now = _time.time()
    if now - _probe_state["last"] < 12:
        return False
    _probe_state["last"] = now

    try:
        from .sources.instsci import convert_url
    except Exception:
        return False

    try:
        jar = {}
        for c in context.cookies():
            if "wengine_vpn_ticket" in str(c.get("name", "")).lower():
                jar[c["name"]] = c["value"]
        if not jar:
            return False
    except Exception:
        return False

    try:
        import requests as _requests
        probe = convert_url("https://www.nature.com", base, config)
        sess = _requests.Session()
        sess.trust_env = False
        for c in context.cookies():
            sess.cookies.set(c["name"], c["value"],
                             domain=c.get("domain") or None,
                             path=c.get("path") or "/")
        resp = sess.get(probe, timeout=20, allow_redirects=True)
        landed = resp.url.lower()
    except Exception:
        return False

    if "cas/login" in landed or "/login" in landed or "passport.ustc" in landed:
        return False
    return resp.status_code == 200

return open_login_browser(
    base, config, cookie_file=cookie_file, detect_login=_detect, max_wait=600
)

